func init() {
	type vowel struct{ b [2][5]biq }
	defFX("vowel", 1, map[string]float64{"voice": 0, "vowel_sound": 1},
		func(float64) any { return &vowel{} },
		func(f *simpleFX, out, in []float32) {
			s := f.st.(*vowel)
			base := 5*int(f.g("voice")) + 5*int(f.g("vowel_sound")) - 5
			if base < 0 || base+5 > len(vowelFreqs) {
				base = 0
			}
			for ch := range s.b {
				for k := range s.b[ch] {
					z1, z2 := s.b[ch][k].z1, s.b[ch][k].z2
					s.b[ch][k] = bBandPass(vowelFreqs[base+k], vowelBWs[base+k]*vowelAmps[base+k], f.sr)
					s.b[ch][k].z1, s.b[ch][k].z2 = z1, z2
				}
			}
			const fudge = 5
			stereo(out, in, func(ch int, x float64) float64 {
				var y float64
				for k := range s.b[ch] {
					y += s.b[ch][k].run(x * fudge)
				}
				return y * fudge
			})
		})
}

var _ = math.Pi
